async function tbClose(){ /* r108: ✕ · Cancel · الرجوع من المسودة — الخروج بلا حفظ. تعديلات؟ ورقة واحدة؛ وإلا يُغلق بصمت */ if (!TB || TB.closing || TB.saving) return; /* كتابة في الطريق: لا خروج حتى تعود */ if (tbDirty()){ const tb = TB; tb.closing = true; let ok = false; try{ ok = await mpConfirm('What you changed since the last save will be lost.', { title: 'Discard your changes?', ok: 'Discard', cancel: 'Keep editing', danger: true }); } finally { tb.closing = false; } if (!ok || TB !== tb) return; try{ logTiming('TB-SESSION · closed · changes discarded'); }catch(_){} } tbCloseNow(false); }
