async function tbSaveDraft(){ /* r108 (اقتراح المالك ١٦:١٠): خطة لم تُعتمد تُحفظ مسودة وتُكمل لاحقًا */ if (!TB || !TB.plan || TB.saving) return; if (tbDTEmpty()){ showToast('Nothing to save yet — add a stop or a name'); return; } const tb = TB; tbBusy(tb, true); let r; try{ r = await tbSaveNow(); } finally { tbBusy(tb, false); } if (r === 'discarded'){ if (TB === tb) tbCloseNow(false); return; } if (TB !== tb || r === 'guard' || r === 'failed' || mpUnsaved.trips || currentUserSuspended) return; /* الحارس أعادها · أو الكتابة فشلت وقالت ورقتها — المحرّر يبقى مفتوحًا */ tbRender(); showToast(tbDirty() ? 'Saved as a draft ✓ — what you changed meanwhile is not saved yet' : tb.dayPlan ? 'Day plan saved as a draft ✓ — keep going, or Cancel to leave' : 'Saved as a draft ✓ — keep going, or Cancel to leave'); }
