function tbFootHtml(canApprove, hint){ /* r108: خطة لم تُعتمد Cancel · Save as draft · Approve — ومعتمدة Cancel · Done */ const ap = (tbTrip() || {}).status === 'approved'; return '<div class="tb-foot' + (ap ? ' two' : '') + '"><button type="button" class="btn btn-ghost" onclick="tbClose()">Cancel</button>' + (ap ? '<button type="button" class="cta tb-cta" onclick="tbApprove()">Done</button>' : '<button type="button" class="btn btn-ghost" onclick="tbSaveDraft()">Save as draft</button><button type="button" class="cta tb-cta" ' + (canApprove ? '' : 'disabled') + ' onclick="tbApprove()">Approve</button>') + '</div>' + (hint || ''); }
