function tbNearbyCities(cityId){ const all = cityListAllCities(); const me = all.find(function(x){ return x.id === cityId; }); if (!me || typeof me.lat !== 'number' || typeof me.lng !== 'number') return []; return all.filter(function(x){ return x.id !== cityId && typeof x.lat === 'number' && typeof x.lng === 'number' && !(TB && TB.cities.some(function(c){ return c.cityId === x.id; })); }).map(function(x){ return { id: x.id, name: x.name, min: tbDriveMin(me, x) }; }).filter(function(x){ return x.min !== null && x.min <= TB_NEAR_MAX_MIN; }).sort(function(a, b){ return a.min - b.min || String(a.name).localeCompare(String(b.name)); }); } // مدن الرحلة نفسها ليست «قريبة» — لها بابها
