async function tbNearToggle(otherId){ if (!TB || !TB.pick) return; const pickCity = TB.pick; const near = tbNearOn(pickCity); if (near[otherId]){ delete near[otherId]; tbRender(); return; } near[otherId] = true; if (!TB_PLACES[otherId + '|mine']){ const body = document.getElementById('tbBody'); if (body) body.innerHTML = '<div class="mp-empty mini">Loading…</div>'; await tbLoadPlaces(otherId, 'mine'); } if (!TB || TB.pick !== pickCity) return; tbRender(); if (!(TB_PLACES[otherId + '|mine'] || []).length){ const c = cityListAllCities().find(function(x){ return x.id === otherId; }); showToast('No places in ' + ((c && c.name) || 'that city') + ' yet'); } } // القراءة عند الضغط فقط (قراءتان لكل مدينة، مرة بالجلسة)
