  const out = []; const cats = plCatsAll().concat(ownerUid ? [] : privateCategoryList().map(function(c){ return { id: c.id, name: c.name, section: 'Private', sectionId: 'private' }; }));
  cats.forEach(function(c){ /* r102-ب: Stay وTransportation يدخلان الاختيار بترتيب الشجرة (كان ب-٨ يستثنيهما) */ const arr = ((links[c.id] || {}).places || []).filter(function(p){ return p && (p.name || p.url); }); arr.forEach(function(p){ const ref = { sourceType: ownerUid ? 'community' : 'mylist', cityId: cityId, subcatId: c.id, placeId: p.id || hashUrl(p.url || ''), sourceUid: ownerUid || null }; out.push({ key: tbKey(ref), ref: ref, name: p.name || 'Place', area: p.area || '', town: String(p.town || '').trim(), geo: (p.geo && typeof p.geo.lat === 'number') ? { lat: p.geo.lat, lng: p.geo.lng } : null, note: String(p.note || '').trim().slice(0, 200), /* r101-ب: الملاحظة تُعرض في يوم الرحلة */ sec: c.sectionId || '', catId: c.id, path: (c.section ? c.section + ' › ' : '') + c.name, owner: ownerName || '' }); }); });
