    if (src === 'mine' || src === 'stay' || src === 'start'){ let links = {}; if (cityId === cityListCityId && myCityListData && myCityListData.categories) links = Object.assign({}, myCityListData.categories); else { try{ const d = await mpData.cityLists.get(currentUser.uid, cityId); links = Object.assign({}, (d && d.categories) || {}); }catch(e){} } try{ Object.assign(links, await mpData.privatePlaces.get(currentUser.uid, cityId)); }catch(e){} out = (src === 'stay') ? (function(rows){ return rows.filter(function(r){ return r.sec === 'stay'; }).concat(rows.filter(function(r){ return r.sec !== 'stay'; })); })(tbRowsFromLinks(links, cityId, null, '', true).filter(function(r){ return r.sec !== 'transportation'; })) : (src === 'start') ? tbRowsFromLinks(links, cityId, null, '', true) /* r105-٣: نقطة الانطلاق — النقل والإقامة معًا */ : tbRowsFromLinks(links, cityId, null, ''); } /* r102-ب: مصدر الإقامة بلا النقل */ /* ب-٨: المدينة المفتوحة تُقرأ من الذاكرة الحيّة؛ مصدر stay للإقامة يشمل تصنيف Stay */
