async function tbStopReadShare(text){ const dr = tbStopDraft; if (!dr) return; const r = parseMapsShare(text); if (!r.url){ showToast('No link found in the pasted text'); return; } dr.url = r.url; if (r.name && !dr.name.trim()) dr.name = r.name; try{ const pt = await tkPlusPoint(text, await tbStopPlusRef()); if (pt && !pt.err && typeof pt.lat === 'number' && !dr.geo){ dr.geo = { lat: +(+pt.lat).toFixed(5), lng: +(+pt.lng).toFixed(5) }; dr.where = pt.how === 'code' ? 'Plus code' : 'pin link'; } }catch(_){} tbStopRender(); if (!dr.name.trim()) await tbStopResolve(r.url); else showToast('Read ✓ — name filled'); } /* r93-٣: نص المشاركة → الرابط والاسم (والموضع إن حمله الرابط) */
